// static
bool UnionTraits<::extensions::mojom::MessageData::DataView, ::extensions::mojom::MessageDataPtr>::Read(
    ::extensions::mojom::MessageData::DataView input,
    ::extensions::mojom::MessageDataPtr* output) {
  using UnionType = ::extensions::mojom::MessageData;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kJson: {
      std::string result_json{};
      if (!input.ReadJson(&result_json))
        return false;

      *output = UnionType::NewJson(
          std::move(result_json));
      break;
    }
    case Tag::kStructuredMessage: {
      ::blink::CloneableMessage result_structured_message{};
      if (!input.ReadStructuredMessage(&result_structured_message))
        return false;

      *output = UnionType::NewStructuredMessage(
          std::move(result_structured_message));
      break;
    }
    default:

      return false;
  }
  return true;
}

